"use client";

import { useEffect } from "react";
import { useAppDispatch, useAppSelector } from "@/store/hooks";
import { fetchProducts } from "@/store/slices/productSlice";
import { addToCart } from "@/store/slices/cartSlice";

// 🔥 helper (you can move to utils later)
const optimizeImage = (url?: string, width = 500) => {
  if (!url) return "/placeholder.png";
  return url.includes("/upload/")
    ? url.replace("/upload/", `/upload/f_auto,q_auto,w_${width}/`)
    : url;
};

const ProductGrid = () => {
  const dispatch = useAppDispatch();
  const { items, loading, error } = useAppSelector(
    (state) => state.products
  );

  useEffect(() => {
    dispatch(fetchProducts());
  }, [dispatch]);

  // 🔥 Loading Skeleton (better UX than plain text)
  if (loading) {
    return (
      <div className="grid grid-cols-2 md:grid-cols-4 gap-6 p-6">
        {Array.from({ length: 8 }).map((_, i) => (
          <div
            key={i}
            className="bg-white p-4 rounded-lg shadow animate-pulse"
          >
            <div className="h-40 bg-gray-200 rounded mb-3" />
            <div className="h-4 bg-gray-200 rounded mb-2" />
            <div className="h-4 bg-gray-200 w-1/2 rounded mb-3" />
            <div className="h-8 bg-gray-200 rounded" />
          </div>
        ))}
      </div>
    );
  }

  // ❌ Error state
  if (error) {
    return (
      <p className="p-6 text-red-500">
        Failed to load products. Try again.
      </p>
    );
  }

  // ⚠️ Empty state
  if (!items?.length) {
    return (
      <p className="p-6 text-gray-500">
        No products available.
      </p>
    );
  }

  return (
    <div className="grid grid-cols-2 md:grid-cols-4 gap-6 p-6">
      {items.map((product) => {
        const productId = product._id; // ✅ fixed
        const imageSrc = optimizeImage(product.image, 400);

        return (
          <div
            key={productId}
            className="bg-white border rounded-lg p-4 hover:shadow-md transition flex flex-col"
          >
            <img
              src={imageSrc}
              alt={product.name}
              className="h-40 w-full object-cover mb-3 rounded"
              loading="lazy" // 🔥 important
            />

            <h2 className="font-medium text-sm line-clamp-2 min-h-[40px]">
              {product.name}
            </h2>

            <p className="text-orange-600 font-bold mt-1">
              ₦{Number(product.price || 0).toLocaleString()}
            </p>

            <button
              onClick={() =>
                dispatch(
                  addToCart({
                    id: productId,
                    name: product.name,
                    price: product.price,
                    image: product.image,
                    quantity: 1,
                  })
                )
              }
              className="mt-auto w-full bg-yellow-400 hover:bg-yellow-500 active:scale-95 transition text-black py-2 rounded font-medium"
            >
              Add to Cart
            </button>
          </div>
        );
      })}
    </div>
  );
};

export default ProductGrid;